#!/usr/bin/env node
import { readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const dir = fileURLToPath(new URL("../src/sysml/generated/", import.meta.url));
const stamp = `// @ts-nocheck
/* Generated by antlr-ng from grammar/ (daltskin/sysml-v2-grammar v2026.05.0). Do not edit. */
`;

const names = await readdir(dir);
for (const name of names) {
  if (!name.endsWith(".ts")) continue;
  const abs = join(dir, name);
  const body = await readFile(abs, "utf8");
  if (body.startsWith("// @ts-nocheck")) continue;
  await writeFile(abs, stamp + body);
}
